import * as React from "react";
import { cn } from "cn";
import { Dialog as DialogPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";
import { Button } from "./button";
import { Icon } from "./icon";

import { useOwnedEscape } from "../lib/use-owned-escape";

import overlay from "./overlay.module.css";

function Dialog({ ...props }: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />;
}

const DialogTrigger = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Trigger>
>(({ ...props }, ref) => {
  return <DialogPrimitive.Trigger ref={ref} data-slot="dialog-trigger" {...props} />;
});
DialogTrigger.displayName = "DialogTrigger";

function DialogPortal({ ...props }: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return (
    <DialogPrimitive.Portal
      container={useV4PortalContainer()}
      data-slot="dialog-portal"
      {...props}
    />
  );
}

const DialogClose = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Close>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Close>
>(({ ...props }, ref) => {
  return <DialogPrimitive.Close ref={ref} data-slot="dialog-close" {...props} />;
});
DialogClose.displayName = "DialogClose";

const DialogOverlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => {
  return (
    <DialogPrimitive.Overlay
      ref={ref}
      data-slot="dialog-overlay"
      className={cn("isolate z-50", overlay.scrim, className)}
      {...props}
    />
  );
});
DialogOverlay.displayName = "DialogOverlay";

const DialogContent = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & {
    showCloseButton?: boolean;
  }
>(({ className, children, showCloseButton = true, onEscapeKeyDown, ...props }, ref) => {
  const escape = useOwnedEscape(ref, onEscapeKeyDown);
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        ref={escape.ref}
        data-slot="dialog-content"
        className={cn("z-50", overlay.pop, overlay.dialog, className)}
        {...props}
        onEscapeKeyDown={escape.onEscapeKeyDown}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close data-slot="dialog-close" asChild>
            <Button variant="ghost" className={overlay.close} size="icon-sm">
              <Icon name="x" />
              <span className="sr-only">Close</span>
            </Button>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  );
});
DialogContent.displayName = "DialogContent";

const DialogHeader = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="dialog-header"
      className={cn("flex flex-col gap-2", className)}
      {...props}
    />
  );
});
DialogHeader.displayName = "DialogHeader";

const DialogFooter = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div"> & {
    showCloseButton?: boolean;
  }
>(({ className, showCloseButton = false, children, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="dialog-footer"
      className={cn(
        "-mx-4 -mb-4 flex flex-col-reverse gap-2 rounded-b-xl border-t border-[color:var(--v4-line)] bg-muted/50 p-4 sm:flex-row sm:justify-end",
        className
      )}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      )}
    </div>
  );
});
DialogFooter.displayName = "DialogFooter";

const DialogTitle = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => {
  return (
    <DialogPrimitive.Title
      ref={ref}
      data-slot="dialog-title"
      className={cn("", className)}
      {...props}
    />
  );
});
DialogTitle.displayName = "DialogTitle";

const DialogDescription = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => {
  return (
    <DialogPrimitive.Description
      ref={ref}
      data-slot="dialog-description"
      className={cn(
        "text-muted-foreground *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className
      )}
      {...props}
    />
  );
});
DialogDescription.displayName = "DialogDescription";

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger
};

.scrim {
  position: fixed;
  inset: 0;
  background-color: var(--v4-scrim);
}
.scrim[data-state="open"] {
  animation: fadeIn var(--v4-duration-slow) var(--v4-ease-fade) both;
}
.scrim[data-state="closed"] {
  animation: fadeOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.pop {
  box-sizing: border-box;
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
}
.dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  display: grid;
  width: calc(100% - 2 * var(--v4-space-16));
  max-width: var(--v4-size-dialog);
  max-height: calc(100dvh - 2 * var(--v4-space-16));
  overflow-y: auto;
  translate: -50% -50%;
}
.dialog[data-state="open"] {
  animation: dialogIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.dialog[data-state="closed"] {
  animation: dialogOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.palette {
  top: 33%;
  max-width: var(--v4-size-dialog-wide);
  overflow: hidden;
  translate: -50% 0;
}
.close[data-slot] {
  position: absolute;
  top: calc(
    var(--v4-space-overlay-inset) + (var(--v4-type-title-line-height) - var(--v4-size-nested-md)) /
      2
  );
  inset-inline-end: calc(
    var(--v4-space-overlay-inset) - (var(--v4-size-nested-md) - var(--v4-size-icon)) / 2
  );
}
.sheet {
  --v4-sheet-from: 100% 0;
}
.sheet[data-side="left"] {
  --v4-sheet-from: -100% 0;
}
.sheet[data-side="top"] {
  --v4-sheet-from: 0 -100%;
}
.sheet[data-side="bottom"] {
  --v4-sheet-from: 0 100%;
}
.sheet[data-state="open"] {
  animation: sheetIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.sheet[data-state="closed"] {
  animation: sheetOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.drawer.drawer[data-vaul-drawer] {
  transition-duration: var(--v4-duration-slow);
  transition-timing-function: var(--v4-ease-spring-soft);
  animation-duration: var(--v4-duration-slow);
  animation-timing-function: var(--v4-ease-spring-soft);
  animation-fill-mode: both;
}
.drawer.drawer[data-vaul-drawer][data-state="closed"] {
  transition-duration: var(--v4-duration-exit-slow);
  transition-timing-function: var(--v4-ease-exit);
  animation-duration: var(--v4-duration-exit-slow);
  animation-timing-function: var(--v4-ease-exit);
}
.handle {
  display: none;
  flex: none;
  width: var(--v4-space-48);
  height: var(--v4-space-4);
  margin: var(--v4-space-12) auto 0;
  border-radius: calc(var(--v4-radius-pop) * var(--corners));
  background-color: var(--v4-control);
}
[data-vaul-drawer-direction="bottom"] > .handle {
  display: block;
}
.scrim.scrim[data-vaul-overlay] {
  animation-duration: var(--v4-duration-slow);
  animation-timing-function: var(--v4-ease-fade);
  animation-fill-mode: both;
}
.scrim.scrim[data-vaul-overlay][data-state="closed"] {
  animation-duration: var(--v4-duration-exit-slow);
  animation-timing-function: var(--v4-ease-exit);
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@keyframes dialogIn {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes dialogOut {
  to {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes sheetIn {
  from {
    translate: var(--v4-sheet-from);
  }
}
@keyframes sheetOut {
  to {
    translate: var(--v4-sheet-from);
  }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[data-state="open"],
  .sheet[data-state="open"] {
    animation-name: fadeIn;
  }
  .dialog[data-state="closed"],
  .sheet[data-state="closed"] {
    animation-name: fadeOut;
  }
  .drawer.drawer[data-vaul-drawer] {
    transition: none;
  }
  .drawer.drawer.drawer[data-vaul-drawer][data-state="open"] {
    animation-name: fadeIn;
  }
  .drawer.drawer.drawer[data-vaul-drawer][data-state="closed"] {
    animation-name: fadeOut;
  }
}
